// Cek secret supaya webhook ini tidak bisa dipakai orang lain.
// Kirim secret lewat header "x-webhook-secret" atau query "?secret=".
const secret = String($env.WEBHOOK_SECRET || '').trim();
const req = $input.first().json;
const given = String(req.headers?.['x-webhook-secret'] || req.query?.secret || '').trim();

return [
  {
    json: {
      authorized: secret.length > 0 && given === secret,
      body: req.body && typeof req.body === 'object' ? req.body : {},
    },
  },
];

